-- Zanclus CMS: pilih database tujuan di phpMyAdmin sebelum mengimpor.
-- Tidak membuat database/user, tidak mengandung password, tidak menghapus data.
-- Dapat diimpor kembali: konten dan reservasi yang sudah ada tetap dipertahankan.

CREATE TABLE IF NOT EXISTS zanclus_records (
  id VARCHAR(50) PRIMARY KEY,
  kind VARCHAR(30) NOT NULL,
  payload LONGTEXT NOT NULL,
  version INT NOT NULL DEFAULT 1,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) CHARACTER SET utf8mb4;

CREATE TABLE IF NOT EXISTS zanclus_media (
  id CHAR(36) PRIMARY KEY,
  name VARCHAR(150) NOT NULL,
  mime VARCHAR(40) NOT NULL,
  data MEDIUMBLOB NOT NULL,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) CHARACTER SET utf8mb4;

CREATE TABLE IF NOT EXISTS zanclus_login_attempts (
  id VARCHAR(50) PRIMARY KEY,
  attempts INT NOT NULL,
  window_start BIGINT NOT NULL
);

-- JSON konten awal dalam UTF-8 hex agar aman untuk tanda kutip dan mode SQL.
INSERT IGNORE INTO zanclus_records (id, kind, payload)
VALUES ('site', 'content', CONVERT(X'' USING utf8mb4));
